package com.DecisionMaking.Examples;

public class If_Else_If_lader {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		String city = "Bijnor";
    	if(city == "Bengaluru") {
    		System.out.println("City is in Karnataka");
    	}
    	else if(city == "Greater Noida") {
    		System.out.println("City is in Noida");
    	}
    	else {
    		System.out.println("City is in UP");
    	}

	}

}
